    internal static int FtNl(byte[] b, int i) {
        int k = i;
        while ((k < emon.Port.BlobLen(b)) && (emon.Port.BlobU8(b, k) != 10)) {
            k += 1;
        }
        return k;
    }
    internal static int FtTab(byte[] b, int i, int lim) {
        int k = i;
        while ((k < lim) && (emon.Port.BlobU8(b, k) != 9)) {
            k += 1;
        }
        return k;
    }
    internal static int FtHexval(int c) {
        if ((c >= 48) && (c <= 57)) {
            return c - 48;
        }
        if ((c >= 97) && (c <= 102)) {
            return c - 87;
        }
        return -1;
    }
    internal static int FtHexInto(byte[] b, int from, int to, emon.Port.Cells c) {
        // Decode the hex pairs in b[from, to) into c (cleared first); `-` is
        // the empty string.
        int k = from;
        emon.Port.CellsDrop(c, 0);
        if (((to - from) == 1) && (emon.Port.BlobU8(b, from) == 45)) {
            return 0;
        }
        while ((k + 1) < (to + 0)) {
            emon.Port.CellsPush(c, (FtHexval(emon.Port.BlobU8(b, k)) * 16) + FtHexval(emon.Port.BlobU8(b, k + 1)));
            k += 2;
        }
        return emon.Port.CellsLen(c);
    }
    internal static int FtCompare(emon.Port.Cells @out, byte[] b, int from, int to) {
        // -1 when `out` is exactly the hex in b[from, to) (`-` is empty); -2
        // for a length difference; else the index of the first differing byte.
        int n = (to - from) / 2;
        int i = 0;
        if (((to - from) == 1) && (emon.Port.BlobU8(b, from) == 45)) {
            n = 0;
        }
        if (emon.Port.CellsLen(@out) != n) {
            return -2;
        }
        while (i < n) {
            if (emon.Port.CellsAt(@out, i) != ((FtHexval(emon.Port.BlobU8(b, from + (i * 2))) * 16) + FtHexval(emon.Port.BlobU8(b, from + ((i * 2) + 1))))) {
                return i;
            }
            i += 1;
        }
        return -1;
    }
    internal static int FtDec(byte[] b, int from, int to) {
        int k = from;
        int v = 0;
        while (k < to) {
            v = (v * 10) + (emon.Port.BlobU8(b, k) - 48);
            k += 1;
        }
        return v;
    }
    internal static int FtFilter(byte[] b, int from, int to) {
        // The `pf-filter` code for a filter name, told apart by length.
        int n = to - from;
        if (n == 14) {
            return Pdffilter.PfFHex();
        }
        if (n == 13) {
            return Pdffilter.PfFA85();
        }
        if (n == 9) {
            return Pdffilter.PfFLzw();
        }
        if (n == 11) {
            return Pdffilter.PfFFlate();
        }
        if (n == 15) {
            return 5;
        }
        return 0;
    }
    internal static int FtParm(byte[] b, int from, int to, int key, int dflt) {
        // The value of `key` in `P=1,C=2` parameters (`-` for none): the key is
        // named by its first letter and, for C, its fourth (Columns / Colors).
        // Keys: 80 Predictor, 67 Columns, 99 Colors, 66 BitsPerComponent,
        // 69 EarlyChange.
        int k = from;
        int e = 0;
        int eq = 0;
        int id = 0;
        while (k < to) {
            e = k;
            while ((e < to) && (emon.Port.BlobU8(b, e) != 44)) {
                e += 1;
            }
            eq = k;
            while ((eq < e) && (emon.Port.BlobU8(b, eq) != 61)) {
                eq += 1;
            }
            if (eq < e) {
                id = emon.Port.BlobU8(b, k);
                if (id == 67) {
                    if (emon.Port.BlobU8(b, k + 3) == 111) {
                        id = 99;
                    }
                }
                if (id == key) {
                    return FtDec(b, eq + 1, e);
                }
            }
            k = e + 1;
        }
        return dflt;
    }
    internal static int FtRun(byte[] f, int s1, int s2, int s3, int s4, emon.Port.Cells inp, emon.Port.Cells @out, emon.Port.Cells tmp, emon.Port.Cells st) {
        // Run the row whose filter is f[s1+1, s2), parameters f[s2+1, s3) and
        // input hex f[s3+1, s4): the filter, then a predictor when /Predictor
        // says so. Answers the first non-zero status, with out filled.
        int code = FtFilter(f, s1 + 1, s2);
        int pred = FtParm(f, s2 + 1, s3, 80, 1);
        int early = FtParm(f, s2 + 1, s3, 69, 1);
        int status = 0;
        int n = 0;
        int p = 0;
        n = FtHexInto(f, s3 + 1, s4, inp);
        emon.Port.CellsDrop(@out, 0);
        emon.Port.CellsDrop(tmp, 0);
        if (pred > 1) {
            status = Pdffilter.PfRun(code, emon.Testport.CellsBlob(inp), 0, n, tmp, st, early);
            p = Pdffilter.PfPredict(tmp, 0, emon.Port.CellsLen(tmp), @out, pred, FtParm(f, s2 + 1, s3, 99, 1), FtParm(f, s2 + 1, s3, 66, 8), FtParm(f, s2 + 1, s3, 67, 1));
            if (status == 0) {
                status = p;
            }
        } else {
            status = Pdffilter.PfRun(code, emon.Testport.CellsBlob(inp), 0, n, @out, st, early);
        }
        return status;
    }
    [Xunit.Fact]
    public static void TestEveryRowOfTheFilterCorpus() {
        byte[] f = emon.Testport.TestFile("pdf/filters.txt");
        emon.Port.Cells inp = emon.Port.NewCells();
        emon.Port.Cells @out = emon.Port.NewCells();
        emon.Port.Cells tmp = emon.Port.NewCells();
        emon.Port.Cells st = emon.Port.NewCells();
        int n = emon.Port.BlobLen(f);
        int pos = 0;
        int line = 0;
        int rows = 0;
        int e = 0;
        int s1 = 0;
        int s2 = 0;
        int s3 = 0;
        int s4 = 0;
        int s5 = 0;
        int status = 0;
        while (pos < n) {
            line += 1;
            e = FtNl(f, pos);
            if ((pos < e) && (emon.Port.BlobU8(f, pos) != 35)) {
                rows += 1;
                s1 = FtTab(f, pos, e);
                s2 = FtTab(f, s1 + 1, e);
                s3 = FtTab(f, s2 + 1, e);
                s4 = FtTab(f, s3 + 1, e);
                s5 = FtTab(f, s4 + 1, e);
                status = FtRun(f, s1, s2, s3, s4, inp, @out, tmp, st);
                System.Text.StringBuilder t = emon.Testport.NewText();
                Pdffilter.PfStatusEmitName(t, status);
                emon.Testport.AssertTextSpan(t, f, s4 + 1, s5, "status", line);
                emon.Testport.AssertEqAt(FtCompare(@out, f, s5 + 1, e), -1, "output", line);
            }
            pos = e + 1;
        }
        emon.Testport.AssertThat(rows > 60, "the corpus was read");
    }
